{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Apply a mild deterministic recency cue across all four datasets: observed-item vectors receive scales from 0.9 to 1.1 based only on nonpadding chronological positions. Padding remains zero and mask tokens retain scale 1. The generated predictor imports this same model class, preserving training and inference consistency without changing parameters, topology, loss or optimizer.",
      "edits": [
        {
          "find": "        x = item_vectors * (self.hidden_units ** 0.5) + self.pos_emb(pos)",
          "replace": "        nonpadding = seq != 0\n        chronological_rank = nonpadding.long().cumsum(dim=1) - 1\n        rank_denominator = (nonpadding.sum(dim=1, keepdim=True) - 1).clamp_min(1)\n        relative_recency = chronological_rank.clamp_min(0).to(item_vectors.dtype) / rank_denominator.to(item_vectors.dtype)\n        observed = nonpadding & (seq != self.mask_token)\n        input_scale = torch.where(\n            observed,\n            0.9 + 0.2 * relative_recency,\n            torch.ones_like(relative_recency),\n        )\n        input_scale = input_scale * nonpadding.to(item_vectors.dtype)\n        x = item_vectors * input_scale.unsqueeze(-1) * (self.hidden_units ** 0.5) + self.pos_emb(pos)"
        }
      ]
    }
  ],
  "change_summary": "Add position-derived recency input scaling to each category's single BERT4Rec model, automatically shared by the generated predictor."
}
